// Demo thread for screenshots and demos: a realistic day on the dock in one group conversation.
// Built from whatever is on the dock right now (pallet chips point at real HUs) plus a few of Ola's own inspection photos.
// Head-only button under Messages; nothing here runs on its own.
const PHOTO = {
  avocado: "data:image/jpeg;base64,",
  oranges: "data:image/jpeg;base64,",
  halves: "data:image/jpeg;base64,",
};
const CSV = "data:text/csv;base64,";
const kb = d => Math.round((d.length * 3) / 4);
const uid = () => Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
const at = minsAgo => new Date(Date.now() - minsAgo * 60000).toISOString();

export function demoConversation(s, head, dockRows) {
  const users = (s.users || []).filter(u => u.active !== false);
  const ctrls = users.filter(u => u.role === "Controller" && u.id !== head.id).slice(0, 2);
  const c1 = ctrls[0] || head, c2 = ctrls[1] || ctrls[0] || head;
  const first = u => (u?.name || "").split(" ")[0];
  const rows = (dockRows || []).filter(r => r.hu);
  const pick = (pred, i = 0) => rows.filter(pred)[i] || rows[i] || null;
  const needed = pick(r => r.blocking, 0), needed2 = pick(r => r.blocking, 1), risky = pick(r => /High risk|Now needed/.test(r.priority || ""), 0);
  const palletCtx = r => r ? [{ kind: "pallet", id: r.hu, label: `${r.name || r.article} · ${r.location || ""}`.trim() }] : [];
  const prodCtx = r => { const p = r && (s.products || []).find(p => String(p.articleId) === String(r.article)); return p ? [{ kind: "product", id: p.id }] : []; };
  const insp = (s.inspections || []).filter(i => i.status === "Completed" && i.result).sort((a, b) => (b.completedAt || "").localeCompare(a.completedAt || ""))[0];
  const inspCtx = insp ? [{ kind: "inspection", id: insp.id }] : [];
  const m = (sender, minsAgo, text, extra = {}) => ({ id: uid(), senderId: sender.id, text, at: at(minsAgo), attachments: [], contexts: [], ...extra });
  const messages = [
    m(head, 184, `Morning. Dock sheet is in — ${rows.filter(r => r.blocking).length || 6} pallets flagged needed today. Splitting them now.`),
    m(head, 183, `${first(c1)}, this one first — picking is waiting for it.`, { contexts: palletCtx(needed) }),
    m(head, 182, `${first(c2)}, you take this one. Same supplier had 2 rejections last week — check the whole pallet, not just the top layer.`, { contexts: [...palletCtx(needed2), ...prodCtx(needed2)] }),
    m(c1, 176, "On it 👍"),
    m(c2, 171, "Got it. Opening the product profile first, want to see what we rejected it for."),
    m(c1, 141, "Avocados: 5 of 10 under 4 kg on the penetrometer, the rest between 4 and 6. Spec says 4–6.5. Cutting a sample.", { attachments: [{ id: uid(), kind: "image", name: "avocado-penetrometer.jpg", dataUrl: PHOTO.avocado, size: kb(PHOTO.avocado) }] }),
    m(c1, 137, "Cut 10 — flesh is fine, no browning, stones clean. I'd accept; the soft ones go first in picking.", { attachments: [{ id: uid(), kind: "image", name: "avocado-halves.jpg", dataUrl: PHOTO.halves, size: kb(PHOTO.halves) }] }),
    m(head, 134, "Agreed, accept it. Put the firmness readings in the report so Commercial sees the spread."),
    m(c2, 126, `Oranges from ${needed2?.transporter || "the morning truck"}: Brix 12.8, 12.4, 13.1 — spec min 11. Juice fine. Accepting.`, { attachments: [{ id: uid(), kind: "image", name: "oranges-brix.jpg", dataUrl: PHOTO.oranges, size: kb(PHOTO.oranges) }] }),
    m(c2, 118, "Report is in.", { contexts: inspCtx }),
    m(head, 104, "Six rejections from the night shift are on the sheet — list attached. Whoever is near D-12, check the bananas again before the truck leaves at 14:00.", { attachments: [{ id: uid(), kind: "file", name: "rejections-w41-night.csv", dataUrl: CSV, size: kb(CSV), mime: "text/csv" }] }),
    m(c1, 97, "I'm two docks away, I'll take it.", { contexts: palletCtx(risky) }),
    m(head, 95, "Thanks. Reminder for both of you — the blocked queue has 3 waiting, take them in order after lunch."),
    m(c2, 61, "Blocked #1 done — accepted. Taking #2 now."),
    m(c1, 42, "Bananas: 38% soft, that's a reject. Photos are on the report, rejection form sent to the transporter."),
    m(head, 38, "Good catch. I'll put it in the shift update for the evening crew."),
  ];
  const ids = [head.id, ...ctrls.map(u => u.id)].filter((v, i, a) => a.indexOf(v) === i);
  return { id: uid(), isGroup: true, name: "Dock team · today", participantIds: ids, createdBy: head.id, createdAt: at(185), isActive: true, messages, lastRead: { [head.id]: new Date().toISOString() } };
}
